// FUNCTION: BFME2 0x0048F472 size=58 name=?Rva0048F472IsEqual@@YG_NPAX@Z evidence=?:placeholder
// Whether a member's health equals its maximum (Zero Hour's isMemberHealthy; stdcall here, no this).
Bool __stdcall isMemberHealthy(Object *member)
{
	BodyModuleInterface *body = member->getBodyModule();
	if (body)
	{
		if (body->getHealth() == body->getMaxHealth())
			return TRUE;
	}
	return FALSE;
}

// FUNCTION: BFME2 0x0048F4AC size=247 name=?xfer@AssaultTransportAIUpdate@@MAEXPAVXfer@@@Z evidence=N:ledger
void AssaultTransportAIUpdate::xfer(Xfer *xfer)
{
	AIUpdateInterface::xfer(xfer);
	if (xfer->IsLightCRC())
		return;
	xfer->Version1();
	*xfer == m_currentMembers;
	for (Int i = 0; i < m_currentMembers; ++i)
	{
		XferObjectID(xfer, &m_memberIDs[i]);
		*xfer == m_memberHealing[i];
	}
	*xfer == m_attackMoveGoalPos;
	XferObjectID(xfer, &m_designatedTarget);
	Int state = m_state;
	*xfer == state;
	m_state = (AssaultStateTypes)state;
	*xfer == m_framesRemaining;
	*xfer == m_isAttackMove;
	*xfer == m_isAttackObject;
	*xfer == m_newOccupantsAreNewMembers;
}

