// FUNCTION: BFME2 0x0048F61A size=52 name=?isAttackPointless@AssaultTransportAIUpdate@@QBE_NXZ evidence=N:ledger
Bool AssaultTransportAIUpdate::isAttackPointless() const
{
	if (!m_object->testStatus((ObjectStatusTypes)0x16))
		return false;
	for (Int index = 0; index < m_currentMembers; ++index)
	{
		if (!m_newMember[index])
			return false;
	}
	return true;
}

// FUNCTION: BFME2 0x0048F64E size=66 name=?rva0048F64E@AssaultTransportAIUpdate@@QAE_NPAX@Z evidence=?:placeholder
// Whether a member's health is below the module data's MembersGetHealedAtLifeRatio.
Bool AssaultTransportAIUpdate::isMemberWounded(const Object *member) const
{
	const AssaultTransportAIUpdateModuleData *data = static_cast<const AssaultTransportAIUpdateModuleData *>(getModuleData());
	BodyModuleInterface *body = member->getBodyModule();
	if (body)
	{
		Real ratio = body->getHealth() / body->getMaxHealth();
		if (ratio < data->m_membersGetHealedAtLifeRatio)
			return TRUE;
	}
	return FALSE;
}

// FUNCTION: BFME2 0x0048F690 size=94 name=?Rva0048F690Helper@AssaultTransportAIUpdate@@QAEXXZ evidence=?:placeholder
// Orders every member that is outside the transport back inside.
void AssaultTransportAIUpdate::retrieveMembers()
{
	for (int i = 0; i < m_currentMembers; i++)
	{
		Object *member = TheGameLogic->findObjectByID(m_memberIDs[i]);
		AIUpdateInterface *ai = member ? member->getAI() : NULL;
		if (member && ai)
		{
			Bool contained = member->m_containedBy != NULL;
			if (!contained)
				ai->rva0026C347(getObject(), CMD_FROM_AI);
		}
	}
}

