// FUNCTION: BFME2 0x0048F7A7 size=129 name=?aiDoCommand@AssaultTransportAIUpdate@@UAEXPBUAICommandParms@@@Z evidence=N:ledger
// A command from outside (not the AI itself) resets the assault; an attack-move remembers its goal and an
// attack-object command marks the assault as one on an object; an idle order first calls every member that
// is outside back in. Whatever the command, the base class then handles it.
void AssaultTransportAIUpdate::aiDoCommand(const AICommandParms *parms)
{
	if (parms->m_cmdSource != CMD_FROM_AI)
	{
		switch (parms->m_type)
		{
		case 0xF:	// attack-move to a position
			reset();
			m_attackMoveGoalPos = parms->m_pos;
			m_isAttackMove = TRUE;
			break;
		case 0xB:	// attack an object
		case 0x39:
			reset();
			m_isAttackObject = TRUE;
			break;
		case 5:		// idle
			m_designatedTarget = INVALID_ID;
			retrieveMembers();
			reset();
			break;
		default:
			reset();
			break;
		}
	}
	AIUpdateInterface::aiDoCommand(parms);
}

